const schema=JSON.stringify({type:'object',properties:{workstream:{type:'string'},observations:{type:'array',items:{type:'object',properties:{path:{type:'string'},lines:{type:'string'},claim:{type:'string'}},required:['path','lines','claim']}},existing_tests:{type:'array',items:{type:'string'}},test_recommendations:{type:'array',items:{type:'string'}},boundary_recommendation:{type:'string'},regression_risks:{type:'array',items:{type:'string'}},open_questions:{type:'array',items:{type:'string'}}},required:['workstream','observations','existing_tests','test_recommendations','boundary_recommendation','regression_risks','open_questions']});
const tasks=[
{title:'Listener and autonomy behavior tests',brief:'Inspect listener and autonomy test coverage',scope:'Focus on cogs/ai/genai_listener.py, cogs/ai/genai_common.py, utils/intent.py, and existing tests. Identify the smallest observable tests for eligibility/filtering, debounce replacement, payload behavior, permission gates, cooldowns, intent/confidence, no response, provider/send handoff, and errors. Inspect fixtures/mocking patterns. Do not edit or create files; give paths/line ranges and a minimal ordered test list.'},
{title:'Generation request/result boundary',brief:'Inspect the smallest neutral generation boundary',scope:'Focus on utils/generation.py, providers/base.py, utils/providers.py, context assembly, and generation/provider tests. Recommend the smallest Discord-independent request/result seam that can preserve current behavior. Identify what belongs in adapter vs runtime, the exact current types/functions to reuse, required fields, and imports/coupling to remove. Do not propose broad refactors or edit files.'},
{title:'Regression risks and validation',brief:'Review Week 1 refactor regression risks',scope:'Inspect call sites of safe_generate/generate, ConversationResponse/MessageSegment, attachments, Discord send/reply, persona ID lifecycle, provider results and error handling, plus tests/check scripts. Identify compatibility risks and minimal validation commands/tests. Respect that no production behavior should change except the extraction. Do not edit or create files.'}
];
const mapped=await parallel('Week 1 implementation review',()=>tasks.map(t=>agent('Inspect the current local Freesona checkout at E:\\Documents\\Yanami directly. Read root AGENTS.md first. The task is planning before implementation: read-only only, no edits, no file creation, no tests/formatters. Preserve pre-existing deleted .github Junie workflows and all .manus/outputs contents. If the checkout is inaccessible, say so. '+t.scope+'\nReturn evidence and recommendations in the required JSON schema. Do not speculate beyond inspected code.',{brief:t.brief,schema,sandbox:'shared',effort_level:'standard'})),{schema});
const ok=mapped.filter(r=>r.ok).map(r=>r.value);const failures=mapped.map((r,i)=>r.ok?null:{workstream:tasks[i].title,code:r.error.code,message:r.error.message}).filter(Boolean);
const outSchema=JSON.stringify({type:'object',properties:{synthesis:{type:'string'},minimal_test_plan:{type:'array',items:{type:'string'}},request_result_contract:{type:'string'},migration_steps:{type:'array',items:{type:'string'}},risks:{type:'array',items:{type:'string'}},validation:{type:'array',items:{type:'string'}},open_product_decisions:{type:'array',items:{type:'string'}}},required:['synthesis','minimal_test_plan','request_result_contract','migration_steps','risks','validation','open_product_decisions']});
const reduced=await agent('Synthesize the three code-review results below into a bounded implementation plan for Week 1. This is only pre-edit synthesis. No new repository research, no edits. Prioritize observable behavior tests before a single neutral interaction request/result seam. Reuse current helpers. Clearly separate assumptions from confirmed code. Include minimal test plan, request/result fields, extraction steps preserving old behavior, risks, validation commands, and any product decision required for persona ID. Do not add selective context behavior or fix unrelated debts. Inputs: '+JSON.stringify({results:ok,failures}),{brief:'Synthesize bounded Week 1 test and seam plan',schema:outSchema,sandbox:'shared',effort_level:'standard'});
return {results:ok,failures,reducer:reduced.ok?reduced.value:{error:reduced.error}};

